      { kind: "grid", items: [{ title: "Observation", text: "Many episodes of middle-ear fluid resolve naturally over time." }, { title: "Hearing Monitoring", text: "Repeat hearing tests help decide whether intervention is necessary." }, { title: "Medical Management", text: "Associated nasal allergy or infection may be treated where relevant." }, { title: "Grommet Insertion", text: "Used when persistent fluid and hearing loss justify ventilation of the middle ear." }, { title: "Adenoid Assessment", text: "In selected children, enlarged or infected adenoids may contribute to recurrent middle-ear problems." }, { title: "Hearing Support", text: "Temporary hearing-support strategies may be considered in selected cases." }] }
